
-- Project: Enterprise Data Modelling & Schema Governance Lab
-- File: 02_seed_sample_data.sql
-- Purpose: Populate a fresh database with fictional demonstration data.
-- IMPORTANT: Run after 01_create_schema.sql on a fresh database.
-- Identity IDs are generated by PostgreSQL; they are not hardcoded.

BEGIN;

-- =========================================================
-- 1. USERS
-- =========================================================

INSERT INTO users (username, first_name, last_name, email_address)
VALUES
    ('jlee',   'Jordan', 'Lee',    'jordan.lee@example.com'),
    ('apatel', 'Avery',  'Patel',  'avery.patel@example.com'),
    ('mchen',  'Morgan', 'Chen',   'morgan.chen@example.com');

-- =========================================================
-- 2. ROLES
-- =========================================================

INSERT INTO roles (role_code, role_name, description)
VALUES
    ('ADMIN',    'Administrator', 'System administration'),
    ('REVIEWER', 'Reviewer',      'Reviews submitted applications'),
    ('APPROVER', 'Approver',      'Makes application approval decisions');

-- =========================================================
-- 3. USER-ROLE ASSIGNMENTS
-- =========================================================

INSERT INTO user_roles (user_id, role_id, assigned_by_user_id)
SELECT u.user_id, r.role_id, admin.user_id
FROM (
    VALUES
        ('jlee',   'ADMIN'),
        ('apatel', 'REVIEWER'),
        ('mchen',  'APPROVER')
) AS assignments(username, role_code)
JOIN users u
    ON u.username = assignments.username
JOIN roles r
    ON r.role_code = assignments.role_code
JOIN users admin
    ON admin.username = 'jlee';

-- =========================================================
-- 4. CITIZENS
-- =========================================================

INSERT INTO citizens (first_name, last_name, date_of_birth)
VALUES
    ('Taylor', 'Morgan', DATE '1990-04-12'),
    ('Riley',  'Singh',  DATE '1985-09-23'),
    ('Casey',  'Wilson', DATE '2000-01-17');

-- =========================================================
-- 5. CITIZEN PROFILES
-- =========================================================

INSERT INTO citizen_profiles (
    citizen_id,
    email_address,
    phone_number,
    address_line_1,
    address_line_2,
    city,
    province_code,
    postal_code
)
SELECT
    c.citizen_id,
    profile.email_address,
    profile.phone_number,
    profile.address_line_1,
    profile.address_line_2,
    profile.city,
    profile.province_code,
    profile.postal_code
FROM (
    VALUES
        ('Taylor', 'Morgan',
         'taylor.morgan@example.com', '807-555-0101',
         '100 Demo Street', NULL::text,
         'Thunder Bay', 'ON', 'P7A 1A1'),
        ('Riley', 'Singh',
         'riley.singh@example.com', '807-555-0102',
         '200 Sample Avenue', NULL::text,
         'Thunder Bay', 'ON', 'P7B 2B2'),
        ('Casey', 'Wilson',
         'casey.wilson@example.com', '807-555-0103',
         '300 Example Road', NULL::text,
         'Thunder Bay', 'ON', 'P7C 3C3')
) AS profile(
    first_name, last_name, email_address, phone_number,
    address_line_1, address_line_2, city,
    province_code, postal_code
)
JOIN citizens c
    ON c.first_name = profile.first_name
   AND c.last_name = profile.last_name;

-- =========================================================
-- 6. APPLICATION TYPES
-- =========================================================

INSERT INTO application_types (
    type_code, type_name, description, application_fee
)
VALUES
    ('BUSINESS', 'Business Licence',
     'Demonstration business licence application', 150.00),
    ('PARKING', 'Parking Permit',
     'Demonstration parking permit application', 50.00),
    ('EVENT', 'Special Event Permit',
     'Demonstration special event permit application', 100.00);

-- =========================================================
-- 7. APPLICATIONS
-- =========================================================

INSERT INTO applications (
    citizen_id,
    application_type_id,
    application_number,
    current_status,
    submitted_at
)
SELECT
    c.citizen_id,
    t.application_type_id,
    sample.application_number,
    sample.current_status,
    sample.submitted_at::timestamp
FROM (
    VALUES
        ('Taylor', 'Morgan', 'BUSINESS',
         'APP-2026-0001', 'UNDER_REVIEW', '2026-10-01 09:15:00'),
        ('Riley', 'Singh', 'PARKING',
         'APP-2026-0002', 'APPROVED', '2026-10-03 11:30:00'),
        ('Casey', 'Wilson', 'EVENT',
         'APP-2026-0003', 'SUBMITTED', '2026-10-05 14:00:00')
) AS sample(
    first_name, last_name, type_code,
    application_number, current_status, submitted_at
)
JOIN citizens c
    ON c.first_name = sample.first_name
   AND c.last_name = sample.last_name
JOIN application_types t
    ON t.type_code = sample.type_code;

-- =========================================================
-- 8. DOCUMENTS
-- =========================================================

INSERT INTO documents (
    document_type, file_name, file_reference, document_status
)
VALUES
    ('IDENTITY', 'identity_app_0001.pdf',
     'DEMO-DOC-001', 'VERIFIED'),
    ('APPLICATION', 'parking_app_0002.pdf',
     'DEMO-DOC-002', 'VERIFIED'),
    ('EVENT_PLAN', 'event_plan_app_0003.pdf',
     'DEMO-DOC-003', 'RECEIVED');

-- =========================================================
-- 9. APPLICATION-DOCUMENT LINKS
-- =========================================================

INSERT INTO application_documents (
    application_id, document_id, document_purpose
)
SELECT a.application_id, d.document_id, links.document_purpose
FROM (
    VALUES
        ('APP-2026-0001', 'identity_app_0001.pdf', 'Identity'),
        ('APP-2026-0002', 'parking_app_0002.pdf', 'Application support'),
        ('APP-2026-0003', 'event_plan_app_0003.pdf', 'Event plan')
) AS links(application_number, file_name, document_purpose)
JOIN applications a
    ON a.application_number = links.application_number
JOIN documents d
    ON d.file_name = links.file_name;

-- =========================================================
-- 10. APPLICATION STATUS HISTORY
-- =========================================================

INSERT INTO application_status_history (
    application_id, status_code, changed_by_user_id
)
SELECT a.application_id, history.status_code, u.user_id
FROM (
    VALUES
        ('APP-2026-0001', 'SUBMITTED', 'apatel'),
        ('APP-2026-0001', 'UNDER_REVIEW', 'apatel'),
        ('APP-2026-0002', 'APPROVED', 'mchen'),
        ('APP-2026-0003', 'SUBMITTED', 'apatel')
) AS history(application_number, status_code, username)
JOIN applications a
    ON a.application_number = history.application_number
JOIN users u
    ON u.username = history.username;

-- =========================================================
-- 11. APPLICATION REVIEWS
-- =========================================================

INSERT INTO application_reviews (
    application_id, reviewer_user_id, review_status
)
SELECT a.application_id, u.user_id, review.review_status
FROM (
    VALUES
        ('APP-2026-0001', 'IN_PROGRESS'),
        ('APP-2026-0002', 'COMPLETED'),
        ('APP-2026-0003', 'PENDING')
) AS review(application_number, review_status)
JOIN applications a
    ON a.application_number = review.application_number
JOIN users u
    ON u.username = 'apatel';

-- =========================================================
-- 12. APPLICATION APPROVALS
-- =========================================================

INSERT INTO application_approvals (
    application_id, approver_user_id, decision
)
SELECT a.application_id, u.user_id, 'APPROVED'
FROM applications a
JOIN users u
    ON u.username = 'mchen'
WHERE a.application_number = 'APP-2026-0002';

-- =========================================================
-- 13. PAYMENTS
-- =========================================================


INSERT INTO payments (
    application_id, payment_reference, amount, payment_status, paid_at
)
SELECT a.application_id,
       payment.payment_reference,
       payment.amount,
       payment.payment_status,
       payment.paid_at
FROM (
    VALUES
        ('APP-2026-0001', 'DEMO-PAY-001', 150.00, 'PAID',
         TIMESTAMP '2026-10-01 09:30:00'),
        ('APP-2026-0002', 'DEMO-PAY-002', 50.00, 'PAID',
         TIMESTAMP '2026-10-03 11:45:00'),
        ('APP-2026-0003', 'DEMO-PAY-003', 100.00, 'PENDING',
         NULL::timestamp)
) AS payment(
    application_number, payment_reference, amount, payment_status, paid_at
)
JOIN applications a
    ON a.application_number = payment.application_number;


-- =========================================================
-- 14. AUDIT LOGS
-- =========================================================

INSERT INTO audit_logs (
    user_id, action_type, entity_name, record_id
)
SELECT
    u.user_id,
    log.action_type,
    'applications',
    a.application_id
FROM (
    VALUES
        ('APP-2026-0001', 'apatel', 'REVIEW_STARTED'),
        ('APP-2026-0002', 'mchen',  'APPLICATION_APPROVED'),
        ('APP-2026-0003', 'apatel', 'APPLICATION_RECEIVED')
) AS log(application_number, username, action_type)
JOIN applications a
    ON a.application_number = log.application_number
JOIN users u
    ON u.username = log.username;

COMMIT;
